from pathlib import Path
p=Path('frontend/src/AnalyticsDashboard.tsx');s=p.read_text(encoding='utf-8').replace('IconHistory, IconSearch,','IconHistory,')
s=s.replace('  movements: Bucket[];', '''  movements: Bucket[];
  crateFlows?: { scope: string; producerId: number | null; orchardId: number | null; crateType: number | null; label: string; crate: string; entries: number; exits: number; invalid: number; incoherent: number; physicalVariation: number | null; producerDebt: number | null }[];''')
# Show per type rather than a misleading cross-type sum.
needle='            {exportError ? <Alert color="red">{exportError}</Alert> : null}'
s=s.replace(needle, '''            {!receipts ? <Paper withBorder p="md"><Group justify="space-between"><Text fw={700}>Entrées, sorties et variation physique</Text><Badge variant="light">E − S · période filtrée</Badge></Group><Text size="xs" c="dimmed" mb="sm">Les types restent distincts. La variation n'est ni un stock absolu ni une dette producteur.</Text><Table.ScrollContainer minWidth={620}><Table><Table.Thead><Table.Tr><Table.Th>Station</Table.Th><Table.Th>Type</Table.Th><Table.Th>Entrées E</Table.Th><Table.Th>Sorties S</Table.Th><Table.Th>Variation E−S</Table.Th></Table.Tr></Table.Thead><Table.Tbody>{current.flatMap((s) => (s.crateFlows ?? []).filter((f) => f.scope === 'type').map((f) => <Table.Tr key={`${s.contextId}:${f.crateType}`}><Table.Td>{s.station}</Table.Td><Table.Td>{f.crate} [{f.crateType ?? '?'}]</Table.Td><Table.Td>{format(f.entries,0)}</Table.Td><Table.Td>{format(f.exits,0)}</Table.Td><Table.Td><Text fw={700} c={f.physicalVariation == null ? 'dimmed' : f.physicalVariation < 0 ? 'orange' : 'forest'}>{f.physicalVariation == null ? 'Indisponible' : `${f.physicalVariation > 0 ? '+' : ''}${format(f.physicalVariation,0)}`}</Text></Table.Td></Table.Tr>))}</Table.Tbody></Table></Table.ScrollContainer>{current.every((s) => !(s.crateFlows?.length)) ? <Text size="sm" c="dimmed">Aucun flux détaillé disponible. La version serveur doit être V1.5.1.</Text> : null}</Paper> : null}
            {exportError ? <Alert color="red">{exportError}</Alert> : null}''')
# Add per-producer and orchard flows; do not convert to debts without validated movement nature.
needle='                  <SimpleGrid cols={{ base: 1, md: 2 }}>\n                    {current.map'
s=s.replace(needle, '''                  {!receipts ? <Paper withBorder p="md"><Text fw={700}>Producteurs et vergers · flux enregistrés</Text><Text size="xs" c="dimmed" mb="sm">Soldes dus non calculables : ouverture individuelle et nature prêt/restitution non validées. Les colonnes suivantes décrivent uniquement les entrées et sorties physiques attribuées.</Text><ScrollArea h={300}><Table.ScrollContainer minWidth={700}><Table><Table.Thead><Table.Tr><Table.Th>Station / attribution</Table.Th><Table.Th>Nom</Table.Th><Table.Th>Type</Table.Th><Table.Th>E</Table.Th><Table.Th>S</Table.Th><Table.Th>Contrôle</Table.Th></Table.Tr></Table.Thead><Table.Tbody>{current.flatMap((s) => (s.crateFlows ?? []).filter((f) => f.scope !== 'type').map((f,i) => <Table.Tr key={`${s.contextId}:${f.scope}:${i}`}><Table.Td>{s.station} · {f.scope === 'producer' ? 'Producteur' : 'Verger'}</Table.Td><Table.Td>{f.label} [{f.scope === 'producer' ? f.producerId : f.orchardId}]</Table.Td><Table.Td>{f.crate}</Table.Td><Table.Td>{format(f.entries,0)}</Table.Td><Table.Td>{format(f.exits,0)}</Table.Td><Table.Td>{f.invalid || f.incoherent ? 'À vérifier' : 'Rattachement cohérent ; nature non certifiée'}</Table.Td></Table.Tr>))}</Table.Tbody></Table></Table.ScrollContainer></ScrollArea></Paper> : null}
                  <SimpleGrid cols={{ base: 1, md: 2 }}>
                    {current.map''')
p.write_text(s,encoding='utf-8')
